{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "In humans, UK-224,671 oral bioavailability was 7.5% in the fasted state compared with IV, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "In humans, catechin oral bioavailability was reported as approximately 1.68%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "In normal male control subjects, meperidine/pethidine systemic availability was 0.57 ± 0.12 after oral dosing versus IV, above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred human absolute oral bioavailability records are well below 20% (7.5%, 1.68%, ~5%), while the only above-threshold record (pethidine ~57%) has lower assay-transfer weight; therefore low F is better supported.",
  "evidence_gaps": [
    "Molecule 6 groups records for different compounds (drospirenone vs estradiol), so its inconsistent cards were discounted.",
    "Several records use qualitative 'low' rather than numeric F, limiting threshold precision."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

